WITH scored AS (SELECT *, CUME_DIST() OVER (PARTITION BY device_code ORDER BY pressure DESC NULLS FIRST) pressure_cume_dist, NTILE(4) OVER (PARTITION BY device_code ORDER BY status_bits DESC, id) status_bits_bucket FROM device_readings) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, firmware, pressure_cume_dist FROM scored ORDER BY id NULLS FIRST, firmware DESC LIMIT 20;
